parameters.jsCode:
const body = $input.first().json.body;

const required = ['contract_text'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

if (body.contract_text.trim().length < 100) {
  return [{ json: { valid: false, error: 'Contract text too short. Paste at least one full clause.' } }];
}

const contractTypes = ['employment', 'freelance', 'saas', 'nda', 'lease', 'partnership', 'service', 'vendor', 'consulting', 'other'];
const contractType = contractTypes.includes(body.contract_type) ? body.contract_type : 'other';

return [{
  json: {
    valid: true,
    contractText: body.contract_text.trim().slice(0, 12000),
    contractType,
    partyRole: body.party_role || 'not specified',
    specificClauses: (body.specific_clauses || '').slice(0, 500),
    jurisdiction: body.jurisdiction || '',
    replyEmail: body.reply_email || null,
    requestedAt: new Date().toISOString()
  }
}];

values.content:
Explain this contract to me.

Contract type: {{ $json.contractType }}
My role in this contract: {{ $json.partyRole }}
Jurisdiction: {{ $json.jurisdiction || 'not specified' }}
Specific clauses I want focused on: {{ $json.specificClauses || 'none specified — review the full contract' }}

Contract text:
{{ $json.contractText }}

Return this JSON:
{
  "disclaimer": "one sentence only — that this is plain-language explanation, not legal advice, and they should consult a lawyer for important decisions",
  "contract_summary": "3-4 sentence plain-English summary of what this contract is and what it does overall",
  "my_key_obligations": ["list of the main things the person reading this is required to do under this contract — plain language, be specific"],
  "other_party_obligations": ["what the other party is required to do"],
  "clause_explanations": [
    {
      "clause_name": "name or identifier of the clause",
      "what_it_says": "plain language explanation of what this clause actually means — one paragraph max",
      "real_world_implication": "what this means in practice for the person — what could actually happen because of this clause",
      "risk_level": "one of: standard | watch | negotiate | red_flag",
      "risk_note": "if risk_level is not standard: why it's worth attention and what to do about it"
    }
  ],
  "red_flags": ["any clauses that are genuinely unusual, one-sided, or potentially harmful — be specific about which clause and why"],
  "negotiate_these": [
    {
      "clause": "which clause",
      "why": "why it's worth pushing back on",
      "suggested_ask": "what to ask for instead or in addition"
    }
  ],
  "missing_protections": ["things that would normally be in a contract like this that are absent here — could be an oversight or intentional"],
  "questions_to_ask": ["2-3 questions to ask the other party or your lawyer before signing"]
}

