const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let analysis;
try {
  analysis = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}
const input = $('Validate Input').first().json;
analysis._replyEmail = input.replyEmail;
analysis._contractType = input.contractType;
analysis._partyRole = input.partyRole;
return [{ json: analysis }];

const a = $input.first().json;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const riskConfig = {
  standard:  { color: '#16a34a', bg: '#f0fdf4', label: 'Standard' },
  watch:     { color: '#d97706', bg: '#fffbeb', label: 'Watch' },
  negotiate: { color: '#2563eb', bg: '#eff6ff', label: 'Negotiate' },
  red_flag:  { color: '#dc2626', bg: '#fef2f2', label: 'Red Flag ⚠️' }
};

const clauseCards = (a.clause_explanations || []).map(cl => {
  const rc = riskConfig[cl.risk_level] || riskConfig.standard;
  return `
  <div style="border:1px solid ${rc.color}33;border-radius:8px;margin-bottom:12px;overflow:hidden">
    <div style="background:${rc.bg};padding:8px 16px;display:flex;justify-content:space-between;align-items:center">
      <strong style="font-size:14px;color:#1a1a1a">${esc(cl.clause_name)}</strong>
      <span style="font-size:11px;font-weight:700;color:${rc.color};text-transform:uppercase;letter-spacing:0.4px">${esc(rc.label)}</span>
    </div>
    <div style="padding:12px 16px">
      <div style="font-size:14px;color:#333;line-height:1.65;margin-bottom:8px">${esc(cl.what_it_says)}</div>
      <div style="font-size:13px;color:#555;background:#fafafa;padding:8px 12px;border-radius:4px;line-height:1.5">
        <strong>In practice:</strong> ${esc(cl.real_world_implication)}
      </div>
      ${cl.risk_note ? `<div style="font-size:13px;color:${rc.color};margin-top:8px">↳ ${esc(cl.risk_note)}</div>` : ''}
    </div>
  </div>`;
}).join('');

const obligationList = (items, color) =>
  (items||[]).map(i => `<li style="font-size:14px;margin-bottom:6px;line-height:1.5;color:${color}">${esc(i)}</li>`).join('');

const negotiateCards = (a.negotiate_these || []).map(n =>
  `<div style="border-left:3px solid #2563eb;padding:10px 14px;background:#eff6ff;border-radius:0 6px 6px 0;margin-bottom:10px">
    <div style="font-size:13px;font-weight:700;color:#1d4ed8">${esc(n.clause)}</div>
    <div style="font-size:13px;color:#333;margin:4px 0">${esc(n.why)}</div>
    <div style="font-size:13px;color:#2563eb"><strong>Ask for:</strong> ${esc(n.suggested_ask)}</div>
  </div>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f4f4f2;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#1a1a1a">
<div style="max-width:680px;margin:0 auto">

  <div style="background:#1e293b;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#64748b;margin-bottom:6px">Contract Explainer · ${esc(a._contractType)}</div>
    <div style="font-size:19px;font-weight:700">Your contract, in plain English</div>
    <div style="font-size:12px;color:#94a3b8;margin-top:4px">Role: ${esc(a._partyRole)}</div>
  </div>

  <div style="background:#fef3c7;padding:12px 28px;border:1px solid #fde68a;font-size:13px;color:#92400e">
    ${esc(a.disclaimer)}
  </div>

  <div style="background:#fff;padding:20px 28px;border:1px solid #eee;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:8px">What this contract does</div>
    <p style="font-size:15px;line-height:1.7;color:#333;margin:0">${esc(a.contract_summary)}</p>
  </div>

  <div style="background:#fff;padding:20px 28px;border:1px solid #eee;border-top:3px solid #f0f0f0">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">
      <div>
        <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#dc2626;margin-bottom:8px">Your obligations</div>
        <ul style="list-style:disc;padding-left:16px;margin:0">${obligationList(a.my_key_obligations, '#333')}</ul>
      </div>
      <div>
        <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#16a34a;margin-bottom:8px">Their obligations</div>
        <ul style="list-style:disc;padding-left:16px;margin:0">${obligationList(a.other_party_obligations, '#555')}</ul>
      </div>
    </div>
  </div>

  <div style="background:#fff;padding:20px 28px;border:1px solid #eee;border-top:3px solid #f0f0f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:14px">Clause by clause</div>
    ${clauseCards}
  </div>

  ${(a.red_flags||[]).length ? `<div style="background:#fef2f2;padding:16px 28px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#dc2626;margin-bottom:10px">⚠ Red flags</div>
    ${(a.red_flags||[]).map(rf => `<div style="font-size:14px;color:#7f1d1d;padding:5px 0;border-bottom:1px solid #fee2e2">${esc(rf)}</div>`).join('')}
  </div>` : ''}

  ${negotiateCards ? `<div style="background:#fff;padding:20px 28px;border:1px solid #eee;border-top:3px solid #f0f0f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#2563eb;margin-bottom:12px">Push back on these</div>
    ${negotiateCards}
  </div>` : ''}

  ${(a.missing_protections||[]).length ? `<div style="background:#fff;padding:16px 28px;border:1px solid #eee;border-top:3px solid #f0f0f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#9333ea;margin-bottom:8px">Missing protections</div>
    ${(a.missing_protections||[]).map(m => `<div style="font-size:14px;color:#555;padding:5px 0;border-bottom:1px solid #f5f0ff">${esc(m)}</div>`).join('')}
  </div>` : ''}

  ${(a.questions_to_ask||[]).length ? `<div style="background:#f8faff;padding:16px 28px;border:1px solid #dbe4ff">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#4f46e5;margin-bottom:10px">Ask these before signing</div>
    ${(a.questions_to_ask||[]).map(q => `<div style="font-size:14px;color:#312e81;padding:6px 0;border-bottom:1px solid #e0e7ff">${esc(q)}</div>`).join('')}
  </div>` : ''}

  <div style="background:#1e293b;color:#475569;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Contract Clause Explainer · Not legal advice · ${new Date().toLocaleDateString()}
  </div>
</div>
</body></html>`;

const redFlagCount = (a.red_flags||[]).length;
return [{ json: { html, replyEmail: a._replyEmail, contractType: a._contractType, redFlagCount, analysis: a } }];
